/**
 * Engineering Atlas.
 *
 * Renders the contour terrain generated by `_tools/gen_contours.py` and places
 * a survey marker for each destination. Markers are real focusable elements, so
 * the map is navigable by keyboard and readable by a screen reader; the SVG is
 * decorative and hidden from assistive technology.
 */
import contours from '../data/contours.json';
import { DESTINATIONS, type AtlasDestination } from '../data/content';

interface AtlasOptions {
  svg: SVGSVGElement;
  readout: HTMLElement;
  onNavigate: (href: string) => void;
}

const SVG_NS = 'http://www.w3.org/2000/svg';

function el<K extends keyof SVGElementTagNameMap>(
  name: K,
  attrs: Record<string, string | number> = {},
): SVGElementTagNameMap[K] {
  const node = document.createElementNS(SVG_NS, name);
  for (const [key, value] of Object.entries(attrs)) {
    node.setAttribute(key, String(value));
  }
  return node;
}

/** Destinations that are connected by a survey path, in order. */
const ROUTE = ['systems', 'intelligence', 'product', 'open-source', 'contact'];

export function initAtlas({ svg, readout, onNavigate }: AtlasOptions): void {
  const { width, height } = contours;
  svg.setAttribute('viewBox', `0 0 ${width} ${height}`);
  svg.setAttribute('role', 'presentation');
  svg.setAttribute('aria-hidden', 'true');

  /* --- Survey grid ------------------------------------------------------ */
  const grid = el('g', { class: 'atlas__grid' });
  for (let x = 0; x <= width; x += 100) {
    grid.appendChild(el('line', { x1: x, y1: 0, x2: x, y2: height }));
  }
  for (let y = 0; y <= height; y += 80) {
    grid.appendChild(el('line', { x1: 0, y1: y, x2: width, y2: y }));
  }
  svg.appendChild(grid);

  /* --- Terrain ---------------------------------------------------------- */
  const terrain = el('g', { class: 'atlas__terrain' });
  for (const level of contours.levels) {
    const isMajor = level.index % 3 === 0;
    for (const d of level.paths) {
      terrain.appendChild(
        el('path', {
          d,
          class: isMajor ? 'contour contour--major' : 'contour',
        }),
      );
    }
  }
  svg.appendChild(terrain);

  /* --- Survey paths between destinations -------------------------------- */
  const paths = el('g', { class: 'atlas__paths' });
  const pathEls = new Map<string, SVGPathElement>();

  for (let i = 0; i < ROUTE.length - 1; i += 1) {
    const from = DESTINATIONS.find((d) => d.id === ROUTE[i]);
    const to = DESTINATIONS.find((d) => d.id === ROUTE[i + 1]);
    if (!from || !to) continue;

    // A gentle arc rather than a straight line, so the route reads as a
    // traverse across terrain.
    const mx = (from.x + to.x) / 2;
    const my = (from.y + to.y) / 2 - 26;
    const d = `M${from.x} ${from.y} Q${mx} ${my} ${to.x} ${to.y}`;
    const path = el('path', { d, class: 'atlas__path' });
    paths.appendChild(path);
    pathEls.set(`${from.id}-${to.id}`, path);
  }
  svg.appendChild(paths);

  /* --- Markers ---------------------------------------------------------- */
  const markers = el('g', { class: 'atlas__markers' });
  const markerEls = new Map<string, SVGGElement>();

  DESTINATIONS.forEach((dest, index) => {
    const g = el('g', {
      class: 'marker',
      'data-id': dest.id,
      tabindex: '0',
      role: 'button',
      'aria-label': `${dest.label}. ${dest.hint}`,
    });

    g.appendChild(el('circle', { class: 'marker__hit', cx: dest.x, cy: dest.y, r: 26 }));
    g.appendChild(el('circle', { class: 'marker__ring', cx: dest.x, cy: dest.y, r: 9 }));
    g.appendChild(el('circle', { class: 'marker__dot', cx: dest.x, cy: dest.y, r: 2.5 }));

    const label = el('text', {
      class: 'marker__label',
      x: dest.x + 16,
      y: dest.y + 4,
      // Flip the label to the left of the marker near the right edge so it
      // cannot overflow the frame.
      'text-anchor': dest.x > width - 220 ? 'end' : 'start',
    });
    if (dest.x > width - 220) label.setAttribute('x', String(dest.x - 16));
    label.textContent = dest.label;
    g.appendChild(label);

    const idx = el('text', {
      class: 'marker__index',
      x: dest.x + 16,
      y: dest.y + 16,
      'text-anchor': dest.x > width - 220 ? 'end' : 'start',
    });
    if (dest.x > width - 220) idx.setAttribute('x', String(dest.x - 16));
    idx.textContent = String(index + 1).padStart(2, '0');
    g.appendChild(idx);

    markers.appendChild(g);
    markerEls.set(dest.id, g);
  });

  svg.appendChild(markers);

  /* --- Interaction ------------------------------------------------------ */
  let activeId: string | null = null;

  function showReadout(dest: AtlasDestination, target: SVGGElement) {
    readout.innerHTML = '';

    const h3 = document.createElement('h3');
    h3.textContent = dest.label;
    readout.appendChild(h3);

    const p = document.createElement('p');
    p.textContent = dest.hint;
    readout.appendChild(p);

    const ul = document.createElement('ul');
    for (const item of dest.contents) {
      const li = document.createElement('li');
      li.textContent = item;
      ul.appendChild(li);
    }
    readout.appendChild(ul);

    // Position the readout near the marker, clamped inside the frame.
    const frame = svg.parentElement;
    if (!frame) return;
    const frameRect = frame.getBoundingClientRect();
    const markerRect = target.getBoundingClientRect();

    const scaleX = frameRect.width / width;
    const scaleY = frameRect.height / height;
    const px = dest.x * scaleX;
    const py = dest.y * scaleY;

    const readoutWidth = readout.offsetWidth || 280;
    const readoutHeight = readout.offsetHeight || 160;

    // Place the readout clear of the marker: to the right and below when there
    // is room, otherwise flipped to the left or above.
    const gapX = 30;
    const gapY = 18;

    let left = px + gapX;
    if (left + readoutWidth > frameRect.width - 8) {
      left = px - readoutWidth - gapX;
    }
    left = Math.min(Math.max(left, 8), frameRect.width - readoutWidth - 8);

    let top = py + gapY;
    if (top + readoutHeight > frameRect.height - 8) {
      top = py - readoutHeight - gapY;
    }
    top = Math.min(Math.max(top, 8), frameRect.height - readoutHeight - 8);

    readout.style.left = `${left}px`;
    readout.style.top = `${top}px`;
    readout.setAttribute('data-visible', 'true');
    void markerRect;
  }

  function hideReadout() {
    readout.setAttribute('data-visible', 'false');
  }

  function setActive(id: string | null) {
    if (activeId === id) return;
    activeId = id;

    for (const [key, node] of markerEls) {
      node.setAttribute('data-active', String(key === id));
    }
    for (const [key, node] of pathEls) {
      node.setAttribute('data-active', String(key.includes(id ?? '\u0000')));
    }
  }

  for (const [id, node] of markerEls) {
    const dest = DESTINATIONS.find((d) => d.id === id);
    if (!dest) continue;

    node.addEventListener('pointerenter', () => {
      setActive(id);
      showReadout(dest, node);
    });
    node.addEventListener('pointerleave', () => {
      setActive(null);
      hideReadout();
    });
    node.addEventListener('focus', () => {
      setActive(id);
      showReadout(dest, node);
    });
    node.addEventListener('blur', () => {
      setActive(null);
      hideReadout();
    });

    const activate = () => onNavigate(dest.href);
    node.addEventListener('click', activate);
    node.addEventListener('keydown', (event) => {
      if (event.key === 'Enter' || event.key === ' ') {
        event.preventDefault();
        activate();
      }
    });
  }

  // Hide the readout when the pointer leaves the whole frame.
  svg.parentElement?.addEventListener('pointerleave', () => {
    setActive(null);
    hideReadout();
  });
}
